cd /tmp && python3 - <<'EOF'
import re
s=open('ov_main.js',encoding='utf-8',errors='replace').read()
def unesc(t):
    try:
        return t.encode().decode('unicode_escape')
    except Exception:
        return t
# find chunks containing contest-related Chinese
idx=[m.start() for m in re.finditer('contest',s)]
print(len(idx))
segs=set()
for i in idx:
    segs.add(s[max(0,i-300):i+300])
for k,txt in enumerate(sorted(segs)[:5]):
    print('---',k,'---')
    print(unesc(txt)[:600])
EOF
